      { w: "tranquil", syn: ["calm", "serene", "peaceful", "composed"], ant: ["noisy", "disturbed", "excited"], sent: "The ___ lake was as smooth as a mirror in the early morning.", mis: ["trankuil", "tranquill", "tranqil"] }
